<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useDb} from '../../../stores/db'
import {StatusBadge} from '../../../components/shared'
import {fmtMoney} from '../../../lib/money'
import {placeHold,createBooking} from '../domain'
import {DomainError} from '../../../lib/errors'
const route=useRoute(),router=useRouter(),db=useDb(),step=ref(1),unitId=ref(String(route.query.unit||'unit-12-4')),holdId=ref(''),request=ref(`hold-${Date.now()}`),error=ref(''),primary=ref({name:'Purchaser Demo',email:'buyer@example.com',identityNo:'900101-14-9999'}),joint=ref(false),jointName=ref('Joint Purchaser Demo'),jointEmail=ref('joint@example.com'),jointIdentity=ref('900101-14-9998'),bookingId=ref('')
const unit=computed(()=>db.data.units.find(item=>item.id===unitId.value)),activeHold=computed(()=>db.data.holds.find(item=>item.id===holdId.value))
function doHold(){error.value='';if(!unit.value)return
  try{const hold=placeHold(unit.value.id,unit.value.version,request.value);holdId.value=hold.id;step.value=2}catch(e){error.value=e instanceof Error?e.message:'Unable to place hold'}
}
function simulateCompeting(){error.value='';try{placeHold(unit.value!.id,unit.value!.version,`competing-${Date.now()}`)}catch(e){error.value=e instanceof DomainError?`${e.code}: ${e.message}`:String(e)}}
function retrySame(){try{const hold=placeHold(unit.value!.id,unit.value!.version,request.value);holdId.value=hold.id;error.value='Same request key returned the same hold.'}catch(e){error.value=String(e)}}
function retryDifferent(){try{placeHold(unit.value!.id,unit.value!.version,'different-key')}catch(e){error.value=e instanceof DomainError?`${e.code}: ${e.message}`:String(e)}}
function submit(){error.value='';if(!primary.value.name||!primary.value.email||!primary.value.identityNo){error.value='Primary purchaser name, email/phone and NRIC / Passport No are required.';return}
  try{const booking=createBooking({holdId:holdId.value,purchasers:[{...primary.value,role:'primary'},...(joint.value?[{name:jointName.value,email:jointEmail.value,identityNo:jointIdentity.value,role:'joint' as const}]:[])],requestKey:`booking-${request.value}`});bookingId.value=booking.id;step.value=4}catch(e){error.value=e instanceof Error?e.message:'Unable to create booking'}
}
</script>
<template><div class="page"><header class="page-header"><div><p class="eyebrow">Guided booking</p><h1>Create booking</h1><p>Select, hold, prepare purchaser information and submit without overwriting another request.</p></div><StatusBadge :label="`Step ${step} of 4`" tone="info"/></header><p v-if="error" class="card form-error" role="alert">{{error}}</p><section v-if="step===1" class="card"><h2>1. Select unit</h2><label>Unit<select v-model="unitId"><option v-for="item in db.data.units.filter(u=>u.status==='available')" :key="item.id" :value="item.id">{{item.unitNo}} · {{fmtMoney(item.listPriceMinor)}}</option></select></label><p class="source-meta">Latest version v{{unit?.version}} · {{unit?.status}} · updated 8 Nov 2026</p><el-button type="primary" @click="doHold">Place hold</el-button></section><section v-else-if="step===2" class="card"><h2>2. Hold active</h2><p>Hold {{activeHold?.id}} expires {{activeHold?.expiresAt}}</p><div class="actions"><el-button @click="simulateCompeting">Simulate competing request</el-button><el-button @click="retrySame">Retry same request</el-button><el-button @click="retryDifferent">Reuse key with other payload</el-button><el-button type="primary" @click="step=3">Prepare purchaser</el-button></div></section><section v-else-if="step===3" class="card form-grid"><h2 class="wide">3. Prepare purchaser</h2><label>Primary name<input v-model="primary.name"></label><label>Email<input v-model="primary.email" type="email"></label><label>NRIC / Passport No<input v-model="primary.identityNo"></label><label><input v-model="joint" type="checkbox"> Add joint purchaser</label><template v-if="joint"><label>Joint name<input v-model="jointName"></label><label>Joint email<input v-model="jointEmail"></label><label>Joint NRIC / Passport No<input v-model="jointIdentity"></label></template><div class="wide"><el-button type="primary" @click="submit">Submit booking</el-button></div></section><section v-else class="card"><h2>4. Booking created</h2><p>Stable Booking ID: <strong>{{bookingId}}</strong></p><p>Case ID: <strong>{{db.data.bookings.find(b=>b.id===bookingId)?.caseId}}</strong></p><p>Price snapshot is locked. Enabled payment channels are shown to the purchaser.</p><el-button @click="router.push(`/bookings/${db.data.bookings.find(b=>b.id===bookingId)?.caseId}`)">Open Case 360</el-button></section></div></template>
